function M.catalog()
  return {
    usrcmds = require("cmdlog.bindings.usrcmds").catalog,
    keymaps = require("cmdlog.bindings.keymaps").catalog,
    picker_mappings = require("cmdlog.bindings.picker_mappings").resolved(),
    autocmds = require("cmdlog.bindings.autocmds").catalog,
  }
end

function M.catalog()
  local out = {}
  for _, entry in ipairs(require("cmdlog.bindings.usrcmds").catalog) do
    local key = entry.path or ""
    out[key] = {
      cmd = entry.path and ("Cmdlog " .. entry.path) or "Cmdlog",
      desc = "Cmdlog: " .. entry.desc,
    }
  end
  return out
end

function M.register()
  local composer = require("lib.nvim.usercmd.composer")

  local default_run, routes = nil, {}
  for _, entry in ipairs(M.catalog) do
    if entry.path == nil then
      default_run = handler(entry)
    else
      routes[#routes + 1] = {
        path = { entry.path },
        desc = entry.desc,
        run = handler(entry),
      }
    end
  end

  routes[#routes + 1] = {
    path = { "export" },
    desc = "Export favorites to a JSON file (default: favorites path + .export.json)",
    args = { { name = "path", type = "PATH", optional = true } },
    run = function(ctx)
      require("cmdlog.core.favorites").export(ctx.args.path)
    end,
  }

  routes[#routes + 1] = {
    path = { "import" },
    desc = "Import favorites from a JSON file, merging with the current list",
    args = { { name = "path", type = "PATH" } },
    run = function(ctx)
      require("cmdlog.core.favorites").import(ctx.args.path)
    end,
  }

  composer.verb("Cmdlog", {
    desc = "Command history pickers",
    default = default_run,
    routes = routes,
  })
end

function M.is_known_bad(cmd)
  return load()[cmd] ~= nil
end

function M.get_error(cmd)
  return load()[cmd]
end

function M.get_history()
  return get("history")
end

function M.get_all()
  return get("all")
end

function M.get_project_history()
  local root = M.get_git_root()
  if not root then return {} end
  local data = load()
  return data[root] or {}
end

function M.all()
  return load()
end

function M.describe(cmd)
  local entry = load()[cmd]
  if not entry then return nil end
  return ("used %dx, last %s"):format(entry.count, os.date("%Y-%m-%d %H:%M", entry.last_used))
end

function M.get_tags(cmd)
  return load()[cmd] or {}
end

function M.deduplicate_list(entries)
  return require("lib.lua.tables").dedup_list(entries)
end

function M.process_list(entries, opts)
  opts = opts or {}
  local result = M.reverse_list(entries)

  if opts.unique then result = M.deduplicate_list(result) end

  return result
end

function M.show_history_unique_picker(initial_text)
  local favs = favorites.load()
  local raw = history.get_command_history()
  local entries = process_list(raw, { unique = true })

  local combined = vim.list_extend(vim.deepcopy(favs), entries)
  combined = vim.list_extend(combined, extra_files.get_history())

  picker_utils.open_picker(combined, favs, {
    prompt_title = ":history (unique)",
    fzf_prompt = ":history (unique)> ",
    default_text = initial_text,
    attach_mappings = function(prompt_bufnr, map)
      cycle.attach(prompt_bufnr, map, "nvim")
      return require("cmdlog.ui.mappings")(
        M.show_history_unique_picker,
        history.delete_entry
      )(prompt_bufnr, map)
    end,
  })
end

function M.show_shell_unique_picker(initial_text)
  local favs = favorites.load()
  local raw = shell_mod.get_shell_history()
  local shell_cmds = process_list(raw, { unique = true })

  local combined = vim.list_extend(vim.deepcopy(favs), shell_cmds)

  picker_utils.open_picker(combined, favs, {
    prompt_title = ":shell & favorites (unique)",
    fzf_prompt = ":shell & favorites (unique)> ",
    default_text = initial_text,
    attach_mappings = function(prompt_bufnr, map)
      cycle.attach(prompt_bufnr, map, "shell")
      return require("cmdlog.ui.mappings")(
        M.show_shell_unique_picker,
        shell_mod.delete_entry
      )(prompt_bufnr, map)
    end,
  })
end

function M.show_stats_picker()
  local favs = favorites.load()
  local entries = stats.by_frequency()

  if #entries == 0 then
    notify.info("No usage stats recorded yet")
    return
  end

  picker_utils.open_picker(entries, favs, {
    prompt_title = ":history (by usage)",
    fzf_prompt = ":stats> ",
    attach_mappings = require("cmdlog.ui.mappings")(M.show_stats_picker),
    label = function(entry)
      return stats.describe(entry)
    end,
  })
end

local function has_module(modname)
  return (pcall(require, modname))
end
